def szlenkDeriv (ε : ℝ) (K : Set (WeakDual 𝕜 E)) : Set (WeakDual 𝕜 E) :=
  {x | x ∈ K ∧ ∀ U : Set (WeakDual 𝕜 E), IsOpen U → x ∈ U →
    ∃ a ∈ K ∩ U, ∃ b ∈ K ∩ U,
      ε < ‖WeakDual.toStrongDual a - WeakDual.toStrongDual b‖}

