def szlenkIterate (ε : ℝ) (K : Set (WeakDual 𝕜 E)) (α : Ordinal) :
    Set (WeakDual 𝕜 E) :=
  @transfiniteIterate (OrderDual (Set (WeakDual 𝕜 E))) _ (szlenkDeriv ε)
    Ordinal _ _ _ α K

